// Doors belong to zone edges, using an edge index and a fractional position.
const doorLayer=document.createElementNS(SVG_NS,'g');doorLayer.id='doorsLayer';$('#planWorld').append(doorLayer);
const doorControls=$('#doorControls');
state.doors=[];let doorDrag=null,doorPlacement=false;
function doorEdge(d){const z=state.zones.find(z=>z.id===d.zoneId);if(!z)return null;const p=zonePolygon(z),a=p[d.edge],b=p[(d.edge+1)%p.length];if(!a||!b)return null;const length=Math.hypot(b.x-a.x,b.y-a.y);if(length<1)return null;const width=Math.min(d.widthMm/1000*PX_PER_METRE,length),offset=Math.max(0,Math.min(length-width,d.t*length));return {a,b,length,width,x:a.x+(b.x-a.x)*offset/length,y:a.y+(b.y-a.y)*offset/length,angle:Math.atan2(b.y-a.y,b.x-a.x)*180/Math.PI}}
function snapDoor(point,zoneId=null){let best=null;for(const z of state.zones){if(zoneId&&z.id!==zoneId)continue;const p=zonePolygon(z);p.forEach((a,i)=>{const b=p[(i+1)%p.length],dx=b.x-a.x,dy=b.y-a.y,l2=dx*dx+dy*dy;if(l2<1)return;const length=Math.sqrt(l2),rawT=Math.max(0,Math.min(1,((point.x-a.x)*dx+(point.y-a.y)*dy)/l2)),offset=Math.max(0,Math.min(length,snap(rawT*length))),t=offset/length,distance=Math.hypot(point.x-a.x-dx*t,point.y-a.y-dy*t);if(!best||distance<best.distance)best={zoneId:z.id,edge:i,t,distance}})}return best}
function renderPlanDoors(){
 doorLayer.innerHTML=(state.doors||[]).map(d=>{const e=doorEdge(d);if(!e)return '';const selected=state.selectedKind==='door'&&state.selectedId===d.id,w=e.width;return `<g data-plan-door="${d.id}" transform="translate(${e.x} ${e.y}) rotate(${e.angle})" style="cursor:move"><title>Door · ${Math.round(w/PX_PER_METRE*1000)} mm · drag along a zone edge</title><path d="M0 0H${w}" stroke="white" stroke-width="7"/><g transform="translate(${d.flipX?w:0} 0) scale(${d.flipX?-1:1} ${d.flipY?-1:1})"><rect x="-5" y="-5" width="${w+10}" height="${w+10}" fill="transparent"/><path d="M0 0V${w}M${w} 0A${w} ${w} 0 0 1 0 ${w}" fill="none" stroke="${selected?'#51683b':'#937346'}" stroke-width="${selected?3:2}"/><circle r="${selected?5:3}" fill="#937346"/></g></g>`}).join('');
 const d=state.selectedKind==='door'?state.doors.find(d=>d.id===state.selectedId):null;
 doorControls.innerHTML=`<button class="tool-chip ${doorPlacement?'active':''}" data-door-action="add">+ Door</button>${doorPlacement?'<span style="font-size:11px">Click a zoning edge</span><button class="tool-chip" data-door-action="cancel">Cancel</button>':''}${d?`<label style="font-size:11px">Width mm <input id="planDoorWidth" aria-label="Door width mm" type="number" min="300" step="100" value="${d.widthMm}" style="width:68px"/></label><button class="tool-chip" data-door-action="flipX">Flip left / right</button><button class="tool-chip" data-door-action="flipY">Flip up / down</button><button class="tool-chip" data-door-action="delete">Delete door</button>`:''}`;
}
function startPlanDoor(){if(typeof roomPanel!=='undefined')roomPanel.hidden=true;setCanvasTool('select');doorPlacement=true;svg.style.cursor='crosshair';renderPlanDoors()}
doorControls.addEventListener('click',event=>{const action=event.target.closest('[data-door-action]')?.dataset.doorAction;if(!action)return;if(action==='add')return startPlanDoor();if(action==='cancel'){doorPlacement=false;updateCanvasCursor()}const d=state.doors.find(d=>d.id===state.selectedId);if(d&&['flipX','flipY','delete'].includes(action)){checkpoint();if(action==='delete'){state.doors=state.doors.filter(x=>x.id!==d.id);state.selectedId=null}else d[action]=!d[action]}renderPlanDoors()});
doorControls.addEventListener('change',event=>{if(event.target.id!=='planDoorWidth')return;const d=state.doors.find(d=>d.id===state.selectedId),value=+event.target.value;if(!d||!Number.isFinite(value))return;checkpoint();const e=doorEdge(d),maxWidth=Math.floor(e.length/PX_PER_METRE*10)*100;d.widthMm=Math.min(maxWidth,Math.max(300,Math.round(value/100)*100));renderPlanDoors()});
svg.addEventListener('pointerdown',event=>{if(event.button!==0)return;const target=event.target.closest('[data-plan-door]');if(!target&&!doorPlacement)return;event.preventDefault();event.stopImmediatePropagation();const p=clientToSvg(event);
 if(doorPlacement){const edge=snapDoor(p);if(!edge||edge.distance>24/svg.getScreenCTM().a)return toast('Click close to a zoning boundary');checkpoint();const d={id:'door'+nextId++,zoneId:edge.zoneId,edge:edge.edge,t:edge.t,widthMm:900,flipX:false,flipY:false};state.doors.push(d);state.selectedId=d.id;state.selectedKind='door';doorPlacement=false;updateCanvasCursor()}else{state.selectedId=target.dataset.planDoor;state.selectedKind='door';checkpoint();doorDrag=state.selectedId;svg.setPointerCapture(event.pointerId)}renderZones();renderPlanDoors();},true);
svg.addEventListener('pointermove',event=>{if(!doorDrag)return;event.stopImmediatePropagation();const edge=snapDoor(clientToSvg(event)),d=state.doors.find(d=>d.id===doorDrag);if(edge&&d){Object.assign(d,{zoneId:edge.zoneId,edge:edge.edge,t:edge.t});renderPlanDoors()}},true);
svg.addEventListener('pointerup',event=>{if(!doorDrag)return;event.stopImmediatePropagation();doorDrag=null;if(svg.hasPointerCapture(event.pointerId))svg.releasePointerCapture(event.pointerId)},true);
document.addEventListener('keydown',event=>{if(event.key==='Escape'){doorPlacement=false;renderPlanDoors()}});
// Initial door positions match the user's marked circulation-facing edges.
for(const [type,side,t] of [['Office - Teik','right',.75],['Office - Alvin','right',.7],['Part-time Office - Marvin','right',.75],['Showers + Washrooms','top',.55],['Karaoke','left',.85],['Conference Room','top',.82]]){const z=state.zones.find(z=>z.type===type);if(!z)continue;const point=side==='right'?{x:z.x+z.w,y:z.y+z.h*t}:side==='left'?{x:z.x,y:z.y+z.h*t}:{x:z.x+z.w*t,y:z.y};const edge=snapDoor(point,z.id);state.doors.push({id:'door'+nextId++,zoneId:edge.zoneId,edge:edge.edge,t:edge.t,widthMm:900,flipX:false,flipY:false})}
renderPlanDoors();
